%[text] # Motor Drive Unit - Simulation Case
%[text] ## Constant input signals
%[text] Check that the model runs out of the box.
MotorDriveUnit_Basic_params
target_subsystem = "MotorDriveUnit_Basic_refsub";

stop_time = "10";

model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)
%[text] Test conditions
LoadInputs_MotorDriveUnit_zero
%[text] Initial conditions
initial.LoadInertiaSpeed = simscape.Value(0, "rpm");
initial.motorDriveUnit_RotorSpd_rpm = 0;
initial.ambientTemp_K = motorDriveUnit.ambientTemp_K;
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_Basic_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_refsub");
sim_in = setModelParameter(sim_in, StopTime = stop_time);
applyToModel(sim_in)
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle clutch switch"
  "Axle speed input"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:48476a96]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:81fc8303] %[output:67cbada8] %[output:01eb9e10] %[output:823ea13a] %[output:9fadfba7] %[output:9d26cabd] %[output:8a4aa75f] %[output:0b17a4c8] %[output:4b1b6711] %[output:85b8921f]
  fig.Position(4) = 100;  % height
end %[output:group:48476a96]
